/**
 * Photographs of a hand holding an iPhone, with the exact geometry of the screen in each one.
 * Generated by scripts/landing/mockups.py from the source photos: the screen edges were fitted
 * to the inner edge of the display (sub-pixel, residual under 0.4 px), the corner radius was
 * measured on the photo (62.8 pt), the original screen was painted white and the parts of the
 * hand that sit in front of the display were kept out of the mask, so a finger stays in front
 * of the app. `matrix` maps a 300 x 652.2 screen box onto the display of the photo.
 * Do not edit by hand: run the script again.
 */
export type MockupId = 'hand-front' | 'hand-front-l' | 'hand-tilt' | 'hand-tilt-l' | 'hand-wall' | 'hand-wall-l';

export interface Mockup {
  src: string;
  mask: string;
  /** Size of `src` in pixels; the stage uses the same coordinates. */
  width: number;
  height: number;
  /** Where the cropped mask sits on the photo: x, y, width, height. */
  maskBox: readonly [number, number, number, number];
  /** CSS transform from the 300 x 652.2 screen box to the display in the photo. */
  matrix: string;
}

/** Size of the screen box the app is laid out in (402 x 874 pt, at 300 px wide). */
export const SCREEN_W = 300;
export const SCREEN_H = 652.2;

